129: mojo::PendingRemote<network::mojom::URLLoaderFactory>
130: CreatePrePrefetchURLLoaderFactoryOnUI(BrowserContext* browser_context) {
131:   CHECK_CURRENTLY_ON(BrowserThread::UI, base::NotFatalUntil::M159);
132:   CHECK(browser_context);
133:   TRACE_EVENT0("loading", "CreatePrePrefetchURLLoaderFactoryOnUI");
134: 
135:   // This is the same default network context that should be used in normal
136:   // prefetch's `URLLoaderFactory` on the UI thread, created via
137:   // `PrefetchContainer::GetOrCreateDefaultNetworkContextURLLoaderFactory()`.
138:   network::mojom::NetworkContext* network_context =
139:       browser_context->GetDefaultStoragePartition()->GetNetworkContext();
140: 
141:   if (features::kPrefetchOffTheMainThreadCheckWillCreateURLLoaderFactory
142:           .Get()) {
143:     // Creates the same URLLoaderFactory as the PrefetchContainer's default
144:     // network context's URLLoaderFactory. This is only for Android WebView
145:     // prefetches, assuming:
146:     // - Always browser-initiated.
147:     // - Referring origin is always `std::nullopt` (see
148:     //   `BrowserContext::StartBrowserPrefetchRequest()`).
149:     return CreatePrefetchURLLoaderFactory<
150:         mojo::PendingRemote<network::mojom::URLLoaderFactory>>(
151:         network_context, browser_context,
152:         /*referring_origin=*/std::nullopt,
153:         /*renderer_initiator_info=*/nullptr);
154:   }
155: 
156:   mojo::PendingRemote<network::mojom::URLLoaderFactory> pending_factory;
157:   if (g_url_loader_factory_for_testing) {
158:     CHECK_IS_TEST();
159:     g_url_loader_factory_for_testing->Clone(
160:         pending_factory.InitWithNewPipeAndPassReceiver());
161:   } else {
162:     // Unlike `CreatePrefetchURLLoaderFactory()`, this does use
163:     // `url_loader_factory::HeaderClientOption::kDisallow` and null
164:     // `url_loader_factory::ContentClientParams`. The interceptors that would be
165:     // added by `ContentClientParams` will be added/executed when the
166:     // PrePrefetch is consumed by a `PrefetchContainer`.
167:     pending_factory = url_loader_factory::CreatePendingRemote(
168:         ContentBrowserClient::URLLoaderFactoryType::kPrefetch,
169:         url_loader_factory::TerminalParams::ForNetworkContext(
170:             network_context,
171:             CreatePrefetchURLLoaderFactoryParams(
172:                 // Pre-prefetches are browser-initiated without a referring
173:                 // frame/context, so no creator restrictions apply.
174:                 network::GetNoOpNetworkRestrictionsId()),
175:             url_loader_factory::HeaderClientOption::kDisallow),
176:         /*content_client_params=*/std::nullopt);
177:   }
178:   return pending_factory;
179: }
