503: base::WeakPtr<PrefetchContainer>
504: PrefetchService::CreatePrefetchContainerFromPrePrefetchForTesting(  // IN-TEST
505:     std::unique_ptr<const PrefetchRequest> prefetch_request) {
506:   CHECK_CURRENTLY_ON(BrowserThread::UI, base::NotFatalUntil::M159);
507:   CHECK(base::FeatureList::IsEnabled(
508:       features::kPrefetchOffTheMainThreadForceForTesting));
509:   CHECK(GetBrowserContext());
510: 
511:   std::unique_ptr<PrePrefetchHandle> pre_prefetch_handle;
512:   std::unique_ptr<PrePrefetchService> pre_prefetch_service =
513:       PrePrefetchService::Create(
514:           GetBrowserContext(),
515:           /*embedder_non_ui_thread_update_headers_callbacks=*/{},
516:           /*initial_origin_hint=*/
517:           url::Origin::Create(prefetch_request->key().url()),
518:           /*initial_javascript_enabled_hint=*/
519:           prefetch_request->is_javascript_enabled(),
520:           /*initial_should_append_variations_header_hint=*/
521:           prefetch_request->should_append_variations_header());
522: 
523:   base::WaitableEvent event(base::WaitableEvent::ResetPolicy::MANUAL,
524:                             base::WaitableEvent::InitialState::NOT_SIGNALED);
525:   base::ThreadPool::PostTask(
526:       FROM_HERE, {base::MayBlock()},
527:       base::BindOnce(
528:           [](PrePrefetchService* service_ptr,
529:              std::unique_ptr<const PrefetchRequest> prefetch_request,
530:              std::unique_ptr<PrePrefetchHandle>* pre_prefetch_handle,
531:              base::WaitableEvent* event) {
532:             base::ScopedAllowBaseSyncPrimitivesForTesting allow_blocking;
533:             CHECK(service_ptr);
534:             CHECK(prefetch_request);
535:             *pre_prefetch_handle =
536:                 static_cast<PrePrefetchServiceImpl*>(service_ptr)
537:                     ->StartPrePrefetchRequestForTesting(  // IN-TEST
538:                         std::move(prefetch_request));
539:             event->Signal();
540:           },
541:           pre_prefetch_service.get(), std::move(prefetch_request),
542:           &pre_prefetch_handle, base::Unretained(&event)));
543: 
544:   {
545:     base::ScopedAllowBaseSyncPrimitivesForTesting allow_blocking;
546:     event.Wait();
547:   }
548: 
549:   if (!pre_prefetch_handle) {
550:     return nullptr;
551:   }
552: 
553:   std::unique_ptr<PrePrefetchContainer> pre_prefetch_container =
554:       static_cast<PrePrefetchHandleImpl&>(*pre_prefetch_handle)
555:           .TakePrePrefetchContainerOnUI();
556:   CHECK(pre_prefetch_container);
557:   std::unique_ptr<const PrefetchRequest> prefetch_request_of_pre_prefetch =
558:       pre_prefetch_container->TakePrefetchRequestOnUI();
559:   return CreatePrefetchContainer(std::move(prefetch_request_of_pre_prefetch),
560:                                  std::move(pre_prefetch_container));
561: }
