563: base::WeakPtr<PrefetchContainer> PrefetchService::CreatePrefetchContainer(
564:     std::unique_ptr<const PrefetchRequest> prefetch_request,
565:     std::unique_ptr<PrePrefetchContainer> pre_prefetch_container) {
566:   if (base::FeatureList::IsEnabled(
567:           features::kPrefetchOffTheMainThreadForceForTesting)) {
568:     const bool is_eligible_for_force_pre_prefetch = [&]() {
569:       // If `pre_prefetch_container` is non-null, it's already from the
570:       // off-the-main-thread path and thus don't force the off-the-main-thread
571:       // path again.
572:       if (pre_prefetch_container) {
573:         return false;
574:       }
575: 
576:       const auto origin = url::Origin::Create(prefetch_request->key().url());
577: 
578:       // Currently off-the-main-thread prefetch is only for same-site requests.
579:       if (prefetch_request->IsCrossSiteRequest(origin)) {
580:         return false;
581:       }
582: 
583:       // Also don't trigger off-the-main-thread prefetch if still we need a
584:       // proxy. This mirrors the condition for
585:       // `PreloadingEligibility::kSameSiteCrossOriginPrefetchRequiredProxy`.
586:       if (prefetch_request->IsProxyRequiredForURL(origin) &&
587:           !ShouldPrefetchBypassProxyForTestHost(
588:               prefetch_request->key().url().GetHost())) {
589:         return false;
590:       }
591: 
592:       return true;
593:     }();
594: 
595:     if (is_eligible_for_force_pre_prefetch) {
596:       base::WeakPtr<PrefetchContainer> prefetch_container =
597:           CreatePrefetchContainerFromPrePrefetchForTesting(  // IN-TEST
598:               std::move(prefetch_request));
599:       // While theoretically `prefetch_container` can be null here, we `CHECK()`
600:       // here just to simplify the tests, assuming such theoretical failures
601:       // don't occur on the existing tests.
602:       CHECK(prefetch_container);
603:       return prefetch_container;
604:     }
605:   }
606: 
607:   auto owned_prefetch_container = PrefetchContainer::Create(
608:       base::PassKey<PrefetchService>(), std::move(prefetch_request),
609:       std::move(pre_prefetch_container));
610:   const base::WeakPtr<PrefetchContainer> prefetch_container =
611:       owned_prefetch_container->GetWeakPtr();
